    const { contentEl } = this;
    contentEl.addClass('avm-modal');

    contentEl.createEl('h2', { text: '导入数据' });

    const fileInput = contentEl.createEl('input', {
      attr: { type: 'file', accept: '.csv,.xlsx,.xls' }
    });

