        "-    ",
        "-    const id = this.generateId();",
        "-    const now = Date.now().toString();",
        "-    const app: App = { id, name, createdAt: now, updatedAt: now, version: 1 };",
        "-    ",
        "-    const frontmatter = this.createFrontmatter({",
        "-      id: app.id,",
